# test: are all changed cells on diagonals (both slopes) through key cells (11,8),(12,8),(13,8)?
key = [(11,8),(12,8),(13,8)]
def diag_hits(r,c):
    hits=[]
    for (kr,kc) in key:
        if r+c==kr+kc: hits.append(('anti',kr,kc))
        if r-c==kr-kc: hits.append(('main',kr,kc))
        if r==kr: hits.append(('row',kr,kc))
        if c==kc: hits.append(('col',kr,kc))
    return hits
nohit = [(r,c,v) for r,c,v in changed if not diag_hits(r,c)]
print(len(changed), len(nohit))
